PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

CREATE TABLE Customer(customer_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, country TEXT NOT NULL, segment TEXT NOT NULL, lifecycle_state TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL);
CREATE TABLE Consent(consent_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES Customer(customer_id), channel TEXT NOT NULL, status TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT, source TEXT NOT NULL, captured_at TEXT NOT NULL);
CREATE TABLE Session(session_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES Customer(customer_id), device_type TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT NOT NULL, source TEXT NOT NULL, session_state TEXT NOT NULL);
CREATE TABLE Cart(cart_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES Customer(customer_id), session_id TEXT NOT NULL REFERENCES Session(session_id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_activity_at TEXT NOT NULL, abandonment_threshold_minutes INTEGER NOT NULL, abandoned_at TEXT, status TEXT NOT NULL, subtotal REAL NOT NULL, discount_amount REAL NOT NULL, tax_amount REAL NOT NULL, cart_total REAL NOT NULL, currency TEXT NOT NULL, purchased_at TEXT);
CREATE TABLE CartLine(cart_line_id TEXT PRIMARY KEY, cart_id TEXT NOT NULL REFERENCES Cart(cart_id), sku TEXT NOT NULL, product_name TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, line_total REAL NOT NULL);
CREATE TABLE Campaign(campaign_id TEXT PRIMARY KEY, campaign_name TEXT NOT NULL, channel TEXT NOT NULL, variant TEXT NOT NULL, template_id TEXT NOT NULL REFERENCES MessageTemplate(template_id), scheduled_at TEXT NOT NULL, attribution_window_hours INTEGER NOT NULL, frequency_cap INTEGER NOT NULL, campaign_state TEXT NOT NULL);
CREATE TABLE MessageTemplate(template_id TEXT PRIMARY KEY, channel TEXT NOT NULL, variant TEXT NOT NULL, subject TEXT NOT NULL, body_text TEXT NOT NULL, personalization_fields TEXT NOT NULL);
CREATE TABLE SendAttempt(send_id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES Campaign(campaign_id), customer_id TEXT NOT NULL REFERENCES Customer(customer_id), cart_id TEXT NOT NULL REFERENCES Cart(cart_id), channel TEXT NOT NULL, template_id TEXT NOT NULL REFERENCES MessageTemplate(template_id), message_id TEXT NOT NULL, attempted_at TEXT NOT NULL, send_status TEXT NOT NULL, suppression_reason TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE MessageEvent(message_event_id TEXT PRIMARY KEY, send_id TEXT NOT NULL REFERENCES SendAttempt(send_id), event_type TEXT NOT NULL, event_at TEXT NOT NULL, event_source TEXT NOT NULL);
CREATE TABLE "Order"(order_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES Customer(customer_id), cart_id TEXT NOT NULL REFERENCES Cart(cart_id), ordered_at TEXT NOT NULL, order_status TEXT NOT NULL, subtotal REAL NOT NULL, tax_amount REAL NOT NULL, order_total REAL NOT NULL, currency TEXT NOT NULL, is_late_purchase INTEGER NOT NULL);
CREATE TABLE Attribution(attribution_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES "Order"(order_id), send_id TEXT NOT NULL REFERENCES SendAttempt(send_id), campaign_id TEXT NOT NULL REFERENCES Campaign(campaign_id), attribution_model TEXT NOT NULL, attributed_at TEXT NOT NULL, attributed_revenue REAL NOT NULL, attribution_window_hours INTEGER NOT NULL, is_primary INTEGER NOT NULL);
CREATE TABLE CartEvent(cart_event_id TEXT PRIMARY KEY, cart_id TEXT NOT NULL REFERENCES Cart(cart_id), event_type TEXT NOT NULL, event_at TEXT NOT NULL, old_status TEXT, new_status TEXT NOT NULL, details TEXT NOT NULL);
























































































































































































































































































































































































































































































































































































































































































































































































































































































































































































COMMIT;
